                    <script type="text/javascript">
                        $(document).ready(function() {
                            //reports section
                            $('.page-card .card-link.report-view-btn').click(function(e) {
                                e.preventDefault;
                                var reportname = $(this).find('.card-item-title').html().trim();
                                if (reportname !== '' && reportname !== undefined) {
                                    GTMDatalayer('Report', 'View', reportname);
                                }
                            });

                            $(".showhide").off('change');
                            $(".showhide").on('change', function(event) {
                                event.preventDefault();
                                var report_id = $(this).attr('data-report-id');
                                var type = $(this).attr('data-type');
                                var status = $(this).prop('checked');
                                $.ajax({
                                        method: "POST",
                                        url: site_url + "custom_reports/save_report_preference/",
                                        data: {
                                            report_id: report_id,
                                            status: status,
                                            type: type
                                        }
                                    })
                                    .done(function(msg) {
                                        var result = convert_json_array(msg);
                                        if (result.error == 1) {
                                            common_fancy_alert(result.msg);
                                        } else {
                                            $('#text_msg_' + report_id).html('Your report preference saved successfully.');
                                            $('#msg_' + report_id).show();
                                            //alert('Your report preference saved successfully.');
                                            setTimeout(function() {
                                                $('#msg_' + report_id).hide();
                                            }, 5000);
                                        }
                                    })
                                    .fail(function() {
                                        window.location.reload(true);
                                    });
                            });
                        });

                        function convert_array_json(arr) {
                            return JSON.stringify(arr);
                        }

                        function convert_json_array(str) {
                            return $.parseJSON(str);
                        }

                        function tshowHide(status) {
                            var data = '';
                            $.ajax({
                                type: "post",
                                url: site_url + "custom_reports/rlist/" + status,
                                data: data,
                                success: function(data) {
                                    $("#list").html(data);
                                }
                            });
                        }


                        $(document).ready(function() {
                            $(".star-report").off('click');
                            $(".star-report").on('click', function(event) {
                                event.stopPropagation();
                            });

                            $(".msg_close").off('click');
                            $(".msg_close").on('click', function(event) {
                                $(this).parent().closest('.report-alert-msg').hide();
                                event.stopPropagation();
                                return false;
                            });

                            $(".star-report input[type=checkbox]").off('change');
                            $(".star-report input[type=checkbox]").on('change', function(event) {
                                var status = this.checked;
                                var report_id = this.id;
                                $.ajax({
                                        method: "POST",
                                        url: site_url + "custom_reports/save_report_fav/",
                                        data: {
                                            report_id: report_id,
                                            status: status
                                        }
                                    })
                                    .done(function(msg) {
                                        var result = convert_json_array(msg);
                                        if (result.error == 1) {
                                            common_fancy_alert(result.msg);
                                        } else {
                                            if (status) {
                                                $('#text_msg_' + report_id).html('Report is added to your favourite list.');
                                                $('#msg_' + report_id).show();
                                                /*if($('#fav_master_div').children('#master_'+report_id).length == 0) {
                                                    $('#fav_master_div').append($('#master_'+report_id).clone());
                                                }*/
                                            } else {
                                                $('#text_msg_' + report_id).html('Report is removed from your favourite list.');
                                                $('#msg_' + report_id).show();
                                                //$('#fav_master_div').children('#master_'+report_id).remove();
                                            }
                                            //check_fav_no_record_show();
                                            setTimeout(function() {
                                                $('#msg_' + report_id).hide();
                                            }, 5000);
                                        }
                                    })
                                    .fail(function() {
                                        window.location.reload(true);
                                    });
                                return false;
                            });
                            if ($('#master_' + '1').css('display') != 'none') {
                                $('#fav_master_div').append($('#master_' + '1').clone());
                            }
                            check_fav_no_record_show();
                        });

                        $('.content-scrolling-wrapper').scroll(function() {
                            if ($(this).scrollTop() > 30) {
                                $('.search-sticky').addClass('report-search-sticky');
                            } else {
                                $('.search-sticky').removeClass('report-search-sticky');
                            }
                        });

                        $("#search_report_text").off("keyup");
                        $("#search_report_text").on("keyup", function(e) {
                            if (e.keyCode == 27) {
                                $.fancybox.close();
                                return false;
                            }
                            if (e.keyCode == 13) {
                                if ($('.header_main_a').not('.hidden').length == 1) {
                                    $('.header_main_a').not('.hidden').click();
                                }
                                return false;
                            }
                            var search_val = $("#search_report_text").val().toLowerCase();
                            $('.page-card').removeClass('hidden');
                            if (search_val == '') {
                                $('#search_close').hide();
                                $('.report_div').removeClass('hidden');
                            } else {
                                $('#search_close').show();
                                $('.report_div').addClass('hidden');
                                $(".card-item-title").each(function(index) {
                                    var name_r = $.trim($(this).html().toLowerCase());
                                    if (name_r.indexOf(search_val) !== -1) {
                                        $(this).parent().closest('.report_div').removeClass('hidden');
                                    } else {
                                        var description = '';
                                        if ($(this).parent().parent().next().children('.card-item-des').length > 0) {
                                            description = $.trim($(this).parent().parent().next().children('.card-item-des').html().toLowerCase());
                                        }
                                        if (description != '' && description.indexOf(search_val) !== -1) {
                                            $(this).parent().closest('.report_div').removeClass('hidden');
                                        }
                                    }
                                });
                                $(".page-card").each(function(index) {
                                    if ($(this).children().find('.report_div:visible').length == 0) {
                                        $(this).addClass('hidden');
                                    }
                                });
                            }
                        });


                        function check_fav_no_record_show() {
                            if ($('#fav_master_div').children('.report_div').length > 0) {
                                $('#fav_no_records').hide();
                                $("#fav_master_div .star-report").remove();
                                $("#fav_master_div .report-alert-msg").remove();
                            } else {
                                $('#fav_no_records').show();
                            }
                        }

                        function remove_search() {
                            if ($("#search_report_text").val() != '') {
                                $('#search_close').hide();
                                $("#search_report_text").val('');
                                $('.page-card').removeClass('hidden');
                                $('.report_div').removeClass('hidden');
                            }
                        }

                        $(document).ready(function() {

                            $('.content-scrolling-wrapper').scroll(function() {
                                var pageH = this.scrollHeight;
                                var pageT = this.scrollTop - $('#content').offset().top;
                                $('#marketservice_scrollspy').scrollTop(pageT / pageH * ($('.custom_scroll').height() - $(this).height()));
                            });


                            var offset = 250;
                            offset += parseFloat($('.content-scrolling-wrapper').scrollTop());
                            $('.content-scrolling-wrapper').scrollspy({
                                target: "#marketservice_scrollspy",
                                offset: offset
                            });
                            var offset = 100;

                            function scrollToSection(event) {
                                event.preventDefault();
                                var $section = $($(this).attr('href'));

                                // Remove active class from all nav links
                                $('.marketservice_scrollspy_nav .nav-link').removeClass('active');

                                // Add active class to clicked nav link
                                $(this).addClass('active');

                                $('#content').animate({
                                    scrollTop: $section.offset().top
                                }, 500);
                            }
                            $('[data-scroll]').on('click', scrollToSection);
                            $('#marketservice_scrollspy ul li a').click(function(event) {
                                event.preventDefault();

                                // Remove active class from all nav links
                                $('.marketservice_scrollspy_nav .nav-link').removeClass('active');

                                // Add active class to clicked nav link
                                $(this).addClass('active');

                                $($(this).attr('href'))[0].scrollIntoView();
                                scrollBy(0, -offset);
                                $('#marketservice_scrollspy').removeClass('hamburger-open');
                                $('#hamburger-icon').removeClass('active');
                                $('.overlay').removeClass('overlay-open');
                                $('html').css("overflow", "scroll");
                            });
                            // mobile menu  
                            $('.hrhamburger').click(function(e) {
                                e.preventDefault();
                                $('#marketservice_scrollspy').toggleClass('hamburger-open');
                                $('.overlay').toggleClass('overlay-open');
                                $('html').css("overflow", "hidden");
                            });

                            $('.overlay').click(function(e) {
                                e.preventDefault();
                                $('#hamburger-icon').removeClass('active');
                                $('.overlay').removeClass('overlay-open');
                                $('#marketservice_scrollspy').removeClass('hamburger-open');
                                $('html').css("overflow", "scroll");
                            });

                            $('.marketservice_scrollspy_nav').css({
                                'height': (($(window).height()) - 0) + 'px'
                            });
                            //make new url for back button
                            var afterHashtag = window.location.hash;
                            if (afterHashtag != '') {
                                //window.location.href = afterHashtag;
                                $('a[href="' + afterHashtag + '"]').click();
                            } else {
                                // Set first nav item as active by default
                                $('.marketservice_scrollspy_nav .nav-link').first().addClass('active');
                            }
                        });
                    </script>
                </div>
            </div>
        </div>
    </div>
</section>
@endsection